import{_ as e,c as r,o as h,af as i}from"./chunks/framework.BKeRpnBD.js";const p=JSON.parse('{"title":"夬","description":"焦氏易林注 - 夬","frontmatter":{"title":"夬","description":"焦氏易林注 - 夬"},"headers":[],"relativePath":"classics/jiaoyilin/043.md","filePath":"classics/jiaoyilin/043.md"}'),l={name:"classics/jiaoyilin/043.md"};function n(d,a,t,o,s,c){return h(),r("div",null,[...a[0]||(a[0]=[i('<h1 id="夬" tabindex="-1">夬 <a class="header-anchor" href="#夬" aria-label="Permalink to “夬”">​</a></h1><h3 id="夬-1" tabindex="-1">夬 <a class="header-anchor" href="#夬-1" aria-label="Permalink to “夬”">​</a></h3><h3 id="夬之乾" tabindex="-1">夬之乾 <a class="header-anchor" href="#夬之乾" aria-label="Permalink to “夬之乾”">​</a></h3><h3 id="林辭" tabindex="-1">林辭 <a class="header-anchor" href="#林辭" aria-label="Permalink to “林辭”">​</a></h3><p>狼戾美謀，無言不殊。允厭帝心，悅以獲佑。</p><h3 id="注" tabindex="-1">注 <a class="header-anchor" href="#注" aria-label="Permalink to “注”">​</a></h3><p>此用遇卦《夬》象。伏艮為狼，兌為言，乾亦為言，而兌言與乾言相背，故曰殊。乾為帝、為佑，伏坤為心，兌為悅。</p><h3 id="夬之坤" tabindex="-1">夬之坤 <a class="header-anchor" href="#夬之坤" aria-label="Permalink to “夬之坤”">​</a></h3><h3 id="林辭-1" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-1" aria-label="Permalink to “林辭”">​</a></h3><p>歲暮華落，陽入陰室。萬物伏匿，絕不可得。</p><h3 id="注-1" tabindex="-1">注 <a class="header-anchor" href="#注-1" aria-label="Permalink to “注”">​</a></h3><p>候卦坤居亥，故曰歲暮。遇卦夬為華，後天乾本居亥，陽為陰所牝，故《坤上六》曰&quot;龍戰於野&quot;。戰，即交也，故曰陽入陰室。其義詳《焦氏易詁》中。坤為萬物，坤藏，故曰伏匿。</p><h3 id="夬之屯" tabindex="-1">夬之屯 <a class="header-anchor" href="#夬之屯" aria-label="Permalink to “夬之屯”">​</a></h3><h3 id="林辭-2" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-2" aria-label="Permalink to “林辭”">​</a></h3><p>雞鳴失時，君騷相憂。犬吠不休，行者稽留。</p><h3 id="注-2" tabindex="-1">注 <a class="header-anchor" href="#注-2" aria-label="Permalink to “注”">​</a></h3><p>伏巽為雞，震為鳴，艮為時，坎為失，失時者，言至雞鳴而尚未治事，故下曰騷憂。震為君、為相，坤為憂，艮為犬，震為吠、為行，艮止故稽留。○相，汲古作於，依宋元本。</p><h3 id="夬之蒙" tabindex="-1">夬之蒙 <a class="header-anchor" href="#夬之蒙" aria-label="Permalink to “夬之蒙”">​</a></h3><h3 id="林辭-3" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-3" aria-label="Permalink to “林辭”">​</a></h3><p>鳧鷖遊涇，君子以寧。履德不愆，福祿來成。</p><h3 id="注-3" tabindex="-1">注 <a class="header-anchor" href="#注-3" aria-label="Permalink to “注”">​</a></h3><p>艮為鳧鷖，坎水故曰涇。艮為君子，震為德，為福，艮為成。鳧鷖，《大雅》篇名。首句及第四句皆《詩》語。</p><h3 id="夬之需" tabindex="-1">夬之需 <a class="header-anchor" href="#夬之需" aria-label="Permalink to “夬之需”">​</a></h3><h3 id="林辭-4" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-4" aria-label="Permalink to “林辭”">​</a></h3><p>魃為災虐，風吹雲卻。欲上不得，復歸其宅。</p><h3 id="注-4" tabindex="-1">注 <a class="header-anchor" href="#注-4" aria-label="Permalink to “注”">​</a></h3><p>通《晉》。坎為鬼，離為惡人，故曰魃。坎為災、為雲，坤為風，艮止，故不能上。艮為宅。○首句宋元本作&quot;薄為藩蔽，勁風吹卻&quot;，汲古同，惟蕃蔽作蕃皮，茲依《小畜》之《中孚》校。</p><h3 id="夬之訟" tabindex="-1">夬之訟 <a class="header-anchor" href="#夬之訟" aria-label="Permalink to “夬之訟”">​</a></h3><h3 id="林辭-5" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-5" aria-label="Permalink to “林辭”">​</a></h3><p>東行破車，步入危家。衡門倒垂，無以為主。賣袍續食，糟糠不飽。</p><h3 id="注-5" tabindex="-1">注 <a class="header-anchor" href="#注-5" aria-label="Permalink to “注”">​</a></h3><p>通《明夷》。震為東行、為車、為步，坎為破、為室，故曰危家。艮為門，坎平，故曰衡門。艮覆，故曰倒垂。震為主、為袍、為食、為商，故曰賣。震為糟糠。坤虛，故不飽。○行，汲古作人，依宋元本。</p><h3 id="夬之師" tabindex="-1">夬之師 <a class="header-anchor" href="#夬之師" aria-label="Permalink to “夬之師”">​</a></h3><h3 id="林辭-6" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-6" aria-label="Permalink to “林辭”">​</a></h3><p>青牛白咽，呼我俱因。厯山之下，可以多耕。歲稔時節，民人安寧。</p><h3 id="注-6" tabindex="-1">注 <a class="header-anchor" href="#注-6" aria-label="Permalink to “注”">​</a></h3><p>詳《觀》林。</p><h3 id="夬之比" tabindex="-1">夬之比 <a class="header-anchor" href="#夬之比" aria-label="Permalink to “夬之比”">​</a></h3><h3 id="林辭-7" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-7" aria-label="Permalink to “林辭”">​</a></h3><p>異國殊俗，情不相得。金木為仇，百賊擅殺。</p><h3 id="注-7" tabindex="-1">注 <a class="header-anchor" href="#注-7" aria-label="Permalink to “注”">​</a></h3><p>坤為國、為俗，重坤，故曰異國殊俗。坤為心志，故曰情。艮為金，坎為木、為仇，金克木，故相仇。坎為賊，坤為百、為殺，故曰百賊擅殺。○殺，汲古作谷，依宋元本。</p><h3 id="夬之小畜" tabindex="-1">夬之小畜 <a class="header-anchor" href="#夬之小畜" aria-label="Permalink to “夬之小畜”">​</a></h3><h3 id="林辭-8" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-8" aria-label="Permalink to “林辭”">​</a></h3><p>陰陽精液，膏熟脫拆。胎卵成魄，肇生頭目，日有大喜。</p><h3 id="注-8" tabindex="-1">注 <a class="header-anchor" href="#注-8" aria-label="Permalink to “注”">​</a></h3><p>通《豫》。乾陽坤陰，坎為精液、為膏，巽下斷，故曰拆。震為胎、為卵，坤為魄，故曰胎卵成魄。艮為頭，離為目、為日，震為喜。○脫，宋元本作免，依汲古。胎，汲古作治，喜作吉，均依宋元本。晉語：其魄兆乎民矣。註：魄，形也。成魄者，言由精液而成胎卵之形，頭目以次生也。</p><h3 id="夬之履" tabindex="-1">夬之履 <a class="header-anchor" href="#夬之履" aria-label="Permalink to “夬之履”">​</a></h3><h3 id="林辭-9" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-9" aria-label="Permalink to “林辭”">​</a></h3><p>飢蟲作害，偏多亂纒，緒不可得。</p><h3 id="注-9" tabindex="-1">注 <a class="header-anchor" href="#注-9" aria-label="Permalink to “注”">​</a></h3><p>離虛，故飢。巽為蟲，故曰飢蟲。巽為纒、為緒，離為亂，故難得緒。○蟲，宋元本作蠱，姑依汲古，疑蠶之訛。二三句汲古作&quot;多亂纒綿，不可得秋&quot;，依宋元本。</p><h3 id="夬之泰" tabindex="-1">夬之泰 <a class="header-anchor" href="#夬之泰" aria-label="Permalink to “夬之泰”">​</a></h3><h3 id="林辭-10" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-10" aria-label="Permalink to “林辭”">​</a></h3><p>青蛉如雲，為兵導先。民人冤急，不知東西。</p><h3 id="注-10" tabindex="-1">注 <a class="header-anchor" href="#注-10" aria-label="Permalink to “注”">​</a></h3><p>伏巽為蟲、為青蛉，坤為雲、為眾，故為兵。震為民人、為急，坤憂，故曰冤急。震東兌西，體連，故不知東西。○東西，宋元本作西東，依汲古。青蛉，宋元本作清冷，依《臨》之《夬》校。按：清蛉，淵名，見《山海經》，莊子：茲曰如雲則非淵也，疑清冷為青蛉之訛，抑或古字通用。《呂氏春秋》有人好青蛉者，每朝至海上，蜻蛉從遊者數萬；又《漢志》越巂郡有青蛉縣青蛉水，而《水經註》作蜻蛉，是青蛉與蜻蛉通用，故依《臨》之《夬》校，此似有故實，俟考。</p><h3 id="夬之否" tabindex="-1">夬之否 <a class="header-anchor" href="#夬之否" aria-label="Permalink to “夬之否”">​</a></h3><h3 id="林辭-11" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-11" aria-label="Permalink to “林辭”">​</a></h3><p>班馬旋師，以息勞疲。役夫嘉喜，入戶見妻。</p><h3 id="注-11" tabindex="-1">注 <a class="header-anchor" href="#注-11" aria-label="Permalink to “注”">​</a></h3><p>詳《觀》之《既濟》。</p><h3 id="夬之同人" tabindex="-1">夬之同人 <a class="header-anchor" href="#夬之同人" aria-label="Permalink to “夬之同人”">​</a></h3><h3 id="林辭-12" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-12" aria-label="Permalink to “林辭”">​</a></h3><p>坐爭立訟，紛紛匈匈。卒成禍亂，災及家公。</p><h3 id="注-12" tabindex="-1">注 <a class="header-anchor" href="#注-12" aria-label="Permalink to “注”">​</a></h3><p>詳《大過》之《離》。</p><h3 id="夬之大有" tabindex="-1">夬之大有 <a class="header-anchor" href="#夬之大有" aria-label="Permalink to “夬之大有”">​</a></h3><h3 id="林辭-13" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-13" aria-label="Permalink to “林辭”">​</a></h3><p>鹿食美草，逍遙求飽。趍走山間，過期乃還，肥澤且厭。</p><h3 id="注-13" tabindex="-1">注 <a class="header-anchor" href="#注-13" aria-label="Permalink to “注”">​</a></h3><p>通《比》。艮為鹿，坤為草，坎實故飽。艮為求、為山、為時，故曰期。坎為肥澤。厭，足也。○第三句宋元本作日暮後門，依汲古。</p><h3 id="夬之謙" tabindex="-1">夬之謙 <a class="header-anchor" href="#夬之謙" aria-label="Permalink to “夬之謙”">​</a></h3><h3 id="林辭-14" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-14" aria-label="Permalink to “林辭”">​</a></h3><p>田鼠野雉，意常欲去。拘制籠檻，不得搖動。</p><h3 id="注-14" tabindex="-1">注 <a class="header-anchor" href="#注-14" aria-label="Permalink to “注”">​</a></h3><p>詳《需》之《隨》。</p><h3 id="夬之豫" tabindex="-1">夬之豫 <a class="header-anchor" href="#夬之豫" aria-label="Permalink to “夬之豫”">​</a></h3><h3 id="林辭-15" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-15" aria-label="Permalink to “林辭”">​</a></h3><p>日趨月步，周遍次舍。厯險致遠，無有難處。</p><h3 id="注-15" tabindex="-1">注 <a class="header-anchor" href="#注-15" aria-label="Permalink to “注”">​</a></h3><p>艮日坎月，震為步趨、為周，艮為次舍，坎險震出，故無難處。</p><h3 id="夬之隨" tabindex="-1">夬之隨 <a class="header-anchor" href="#夬之隨" aria-label="Permalink to “夬之隨”">​</a></h3><h3 id="林辭-16" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-16" aria-label="Permalink to “林辭”">​</a></h3><p>天孫帝子，與日月處。光榮於世，福祿祉祉。</p><h3 id="注-16" tabindex="-1">注 <a class="header-anchor" href="#注-16" aria-label="Permalink to “注”">​</a></h3><p>詳《解》之《臨》。祉祉，依宋元本，汲古作祺祉。</p><h3 id="夬之蠱" tabindex="-1">夬之蠱 <a class="header-anchor" href="#夬之蠱" aria-label="Permalink to “夬之蠱”">​</a></h3><h3 id="林辭-17" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-17" aria-label="Permalink to “林辭”">​</a></h3><p>晨風文翰，大舉就溫。昧過我邑，羿無所得。</p><h3 id="注-17" tabindex="-1">注 <a class="header-anchor" href="#注-17" aria-label="Permalink to “注”">​</a></h3><p>詳《小畜》之《革》。文翰，鳥名，見《周書》。</p><h3 id="夬之臨" tabindex="-1">夬之臨 <a class="header-anchor" href="#夬之臨" aria-label="Permalink to “夬之臨”">​</a></h3><h3 id="林辭-18" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-18" aria-label="Permalink to “林辭”">​</a></h3><p>旦生夕死，名曰嬰鬼。不可得祀。</p><h3 id="注-18" tabindex="-1">注 <a class="header-anchor" href="#注-18" aria-label="Permalink to “注”">​</a></h3><p>○祀，宋元本作視，汲古作潛視，依《小畜》之《升》校。</p><h3 id="夬之觀" tabindex="-1">夬之觀 <a class="header-anchor" href="#夬之觀" aria-label="Permalink to “夬之觀”">​</a></h3><h3 id="林辭-19" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-19" aria-label="Permalink to “林辭”">​</a></h3><p>疾貧望幸，使伯南販。開牢擇羊，多得大牂。</p><h3 id="注-19" tabindex="-1">注 <a class="header-anchor" href="#注-19" aria-label="Permalink to “注”">​</a></h3><p>詳《訟》之《遯》。</p><h3 id="夬之噬嗑" tabindex="-1">夬之噬嗑 <a class="header-anchor" href="#夬之噬嗑" aria-label="Permalink to “夬之噬嗑”">​</a></h3><h3 id="林辭-20" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-20" aria-label="Permalink to “林辭”">​</a></h3><p>長城驪山，生民大殘。涉叔發難，唐叔為患。</p><h3 id="注-20" tabindex="-1">注 <a class="header-anchor" href="#注-20" aria-label="Permalink to “注”">​</a></h3><p>艮為城、為山，震為長、為馬，故曰長城驪山。坎為民、為殘破，故曰生民大殘。艮為叔。涉，陳勝字。叔，吳廣字。坎為患，言秦役民築長城、驪山，民不堪命，陳吳因以為亂，而唐叔興起也。漢為唐堯，後劉向高祖頌雲漢帝本系出自唐帝，又《隨》之《剝》雲：唐季發憤，禽滅子嬰，皆指漢高。牟庭謂唐為廣，是不知涉叔為二人，並不知唐季即劉季，故謬誤若斯也。○涉叔，汲古作涉並，依宋元本。牟庭雲唐叔應作廣叔，非。</p><h3 id="夬之賁" tabindex="-1">夬之賁 <a class="header-anchor" href="#夬之賁" aria-label="Permalink to “夬之賁”">​</a></h3><h3 id="林辭-21" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-21" aria-label="Permalink to “林辭”">​</a></h3><p>娶於薑呂，駕迎新婦。少齊在門，夫子歡喜。</p><h3 id="注-21" tabindex="-1">注 <a class="header-anchor" href="#注-21" aria-label="Permalink to “注”">​</a></h3><p>詳《否》之《渙》。</p><h3 id="夬之剝" tabindex="-1">夬之剝 <a class="header-anchor" href="#夬之剝" aria-label="Permalink to “夬之剝”">​</a></h3><h3 id="林辭-22" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-22" aria-label="Permalink to “林辭”">​</a></h3><p>隨時草木，灌枝葉起。扶疏條桃，長大盛美，華沃鑠舒。</p><h3 id="注-22" tabindex="-1">注 <a class="header-anchor" href="#注-22" aria-label="Permalink to “注”">​</a></h3><p>艮為時、為木，坤為草。○草木，宋元本作春草，依汲古。灌枝，宋元本作舊枝，汲古作灌時。今枝依宋元本，灌依汲古，第五句亦有訛字。</p><h3 id="夬之復" tabindex="-1">夬之復 <a class="header-anchor" href="#夬之復" aria-label="Permalink to “夬之復”">​</a></h3><h3 id="林辭-23" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-23" aria-label="Permalink to “林辭”">​</a></h3><p>姬薑既歡，二姓為婚。霜降合好，西施在前。</p><h3 id="注-23" tabindex="-1">注 <a class="header-anchor" href="#注-23" aria-label="Permalink to “注”">​</a></h3><p>震為姬，伏巽為薑，坤為姓，數二，故曰二姓為婚。坤為霜，《荀子》：霜降婚嫁冰泮殺止。西施，吳王妃。陽息至二成兌，為西，故曰在前。○既，汲古作悅，依宋元本。</p><h3 id="夬之無妄" tabindex="-1">夬之無妄 <a class="header-anchor" href="#夬之無妄" aria-label="Permalink to “夬之無妄”">​</a></h3><h3 id="林辭-24" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-24" aria-label="Permalink to “林辭”">​</a></h3><p>戴笠獨宿，晝不見日。勤苦無伐，長勞悲思。</p><h3 id="注-24" tabindex="-1">注 <a class="header-anchor" href="#注-24" aria-label="Permalink to “注”">​</a></h3><p>艮為戴、為笠，巽伏，故曰宿。巽寡，故獨宿。乾為晝、為日，巽伏，故不見日。伏坤為勞、為悲思。○苦代，汲古作勞妄，依宋元本。</p><h3 id="夬之大畜" tabindex="-1">夬之大畜 <a class="header-anchor" href="#夬之大畜" aria-label="Permalink to “夬之大畜”">​</a></h3><h3 id="林辭-25" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-25" aria-label="Permalink to “林辭”">​</a></h3><p>始加元服，二十系室。新婚既樂，伯季有得。</p><h3 id="注-25" tabindex="-1">注 <a class="header-anchor" href="#注-25" aria-label="Permalink to “注”">​</a></h3><p>古者年二十行冠禮，艮為冠，故曰元服。乾為始，故曰始加。兌數二，又數十，艮為室，伏巽為繩，故曰二十系室。易系釋文雲：系，系也，續也。二十系室者，言繼續將有室家也，故下曰新婚。或曰古男子三十而娶，然證以孔子伯魚之年亦不拘也。震為嫁，故曰婚。為樂、為伯，艮為季。○得，汲古作德，依宋元本。</p><h3 id="夬之頤" tabindex="-1">夬之頤 <a class="header-anchor" href="#夬之頤" aria-label="Permalink to “夬之頤”">​</a></h3><h3 id="林辭-26" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-26" aria-label="Permalink to “林辭”">​</a></h3><p>二至靈臺，文所止遊。雲物備具，長樂無憂。</p><h3 id="注-26" tabindex="-1">注 <a class="header-anchor" href="#注-26" aria-label="Permalink to “注”">​</a></h3><p>震為冬至，震之反則夏至矣，故曰二至靈臺。艮為臺，坤為文，艮止震遊，故曰文所止遊。坤為雲、為物、為憂，震樂，故不憂。《左傳》：至日登臺望雲物。○具，宋元本作故，依汲古。文，謂文王，《詩大雅》：&quot;經始靈臺，經之營之&quot;，又曰&quot;王在靈囿&quot;。</p><h3 id="夬之大過" tabindex="-1">夬之大過 <a class="header-anchor" href="#夬之大過" aria-label="Permalink to “夬之大過”">​</a></h3><h3 id="林辭-27" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-27" aria-label="Permalink to “林辭”">​</a></h3><p>久陰霖雨，塗行泥潦。商人休止，市空無寶。</p><h3 id="注-27" tabindex="-1">注 <a class="header-anchor" href="#注-27" aria-label="Permalink to “注”">​</a></h3><p>伏坤為陰、為水，互大坎，故曰霖雨。伏震為大塗，坤為泥潦，震為商人，艮止，故休。巽為市，坤虛，故曰市空。震為玉、為寶，震伏，故曰無寶。○伏止，宋元本作休山，依汲古。寶，各本皆作有，依《革》之《睽》校。</p><h3 id="夬之坎" tabindex="-1">夬之坎 <a class="header-anchor" href="#夬之坎" aria-label="Permalink to “夬之坎”">​</a></h3><h3 id="林辭-28" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-28" aria-label="Permalink to “林辭”">​</a></h3><p>城壞厭境，數為齊病。侵伐不休，君臣擾亂。上下屈竭，士氏乏財。</p><h3 id="注-28" tabindex="-1">注 <a class="header-anchor" href="#注-28" aria-label="Permalink to “注”">​</a></h3><p>互艮為城，坎破，故曰城壞。艮為境，伏巽為齊，坎為病，上下坎故曰數為齊病。震為侵伐，正反震故曰不休。震君艮臣，正反艮震，故曰擾亂、曰上下屈竭。巽為利，巽伏，故乏財。震為士也。林意似指吳伐齊事。○乏，宋元本作無，依汲古。</p><h3 id="夬之離" tabindex="-1">夬之離 <a class="header-anchor" href="#夬之離" aria-label="Permalink to “夬之離”">​</a></h3><h3 id="林辭-29" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-29" aria-label="Permalink to “林辭”">​</a></h3><p>南國盛茂，黍稷醴酒。可以饗養，樂我嘉友。</p><h3 id="注-29" tabindex="-1">注 <a class="header-anchor" href="#注-29" aria-label="Permalink to “注”">​</a></h3><p>通《坎》。艮為國，離南，故曰南國。震為盛茂、為黍稷，坎為酒，兌口，故曰饗養。艮為友，震為樂。○友，依宋元本，汲古作佑。</p><h3 id="夬之鹹" tabindex="-1">夬之鹹 <a class="header-anchor" href="#夬之鹹" aria-label="Permalink to “夬之鹹”">​</a></h3><h3 id="林辭-30" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-30" aria-label="Permalink to “林辭”">​</a></h3><p>憂在心腹，內崩為疾。禍起蕭牆，意如制國。</p><h3 id="注-30" tabindex="-1">注 <a class="header-anchor" href="#注-30" aria-label="Permalink to “注”">​</a></h3><p>通《損》。坤為憂、為心腹、為內、為疾，兌為毀，與坤連體，故曰憂在心腹、內崩為疾。坤為禍、為牆，震為草莽，故曰蕭牆。坤為心意、為國。意如，魯三家季平子名也。《論語》：&quot;吾恐季氏之憂不在顓臾，而在蕭牆之內也&quot;，制國言專政。</p><h3 id="夬之恆" tabindex="-1">夬之恆 <a class="header-anchor" href="#夬之恆" aria-label="Permalink to “夬之恆”">​</a></h3><h3 id="林辭-31" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-31" aria-label="Permalink to “林辭”">​</a></h3><p>朽根刖樹，華葉落去。卒逢大猋，隨風僵僕。</p><h3 id="注-31" tabindex="-1">注 <a class="header-anchor" href="#注-31" aria-label="Permalink to “注”">​</a></h3><p>巽木下斷，故曰朽根，故曰刖樹。兌華，震葉，巽隕，故曰落去。初至四正反巽，故曰猋。猋，迴風也。巽隕落，故僵僕。○大猋，宋元本作火焱，非，依汲古。</p><h3 id="夬之遯" tabindex="-1">夬之遯 <a class="header-anchor" href="#夬之遯" aria-label="Permalink to “夬之遯”">​</a></h3><h3 id="林辭-32" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-32" aria-label="Permalink to “林辭”">​</a></h3><p>樹表為壇，相與期言。午中不會，寵榮棄廢。</p><h3 id="注-32" tabindex="-1">注 <a class="header-anchor" href="#注-32" aria-label="Permalink to “注”">​</a></h3><p>《史記田穰苴傳》：&quot;苴與莊賈期旦日日中會，先期至軍，立表下漏以待，莊賈日午不至，殺之&quot;。艮為壇、為時、為言，故曰期言。艮為日，納丙，故曰日午。乾為寵榮，陰消陽故曰寵榮廢棄。○榮，宋元本作名，依汲古。期，汲古作笑，非，依宋元本。</p><h3 id="夬之大壯" tabindex="-1">夬之大壯 <a class="header-anchor" href="#夬之大壯" aria-label="Permalink to “夬之大壯”">​</a></h3><h3 id="林辭-33" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-33" aria-label="Permalink to “林辭”">​</a></h3><p>四足俱走，奴疲在後。兩戰不勝，敗於東楚。</p><h3 id="注-33" tabindex="-1">注 <a class="header-anchor" href="#注-33" aria-label="Permalink to “注”">​</a></h3><p>震卦數四，故曰四足。艮為奴僕，艮伏，故曰在後。震為戰，兌卦數二，故曰兩戰。震為東、為楚，兌毀故敗。○兩，宋元本作德，非，依汲古。</p><h3 id="夬之晉" tabindex="-1">夬之晉 <a class="header-anchor" href="#夬之晉" aria-label="Permalink to “夬之晉”">​</a></h3><h3 id="林辭-34" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-34" aria-label="Permalink to “林辭”">​</a></h3><p>執轡西朝，回還故處。麥秀傷心，叔父有憂。</p><h3 id="注-34" tabindex="-1">注 <a class="header-anchor" href="#注-34" aria-label="Permalink to “注”">​</a></h3><p>通《需》。兌為西，艮手為執、為拘。轡，所以拘拂馬，疑艮象也。坤為麥、為心，艮為叔，乾為父，坤憂。言箕子朝周，遇殷墟，作麥秀之歌，箕子為紂叔父。○西，汲古作在，依宋元本。有，宋本、汲古作無，依元本。</p><h3 id="夬之明夷" tabindex="-1">夬之明夷 <a class="header-anchor" href="#夬之明夷" aria-label="Permalink to “夬之明夷”">​</a></h3><h3 id="林辭-35" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-35" aria-label="Permalink to “林辭”">​</a></h3><p>夜長日短，陰為陽賊。萬物空枯，藏於北陸。</p><h3 id="注-35" tabindex="-1">注 <a class="header-anchor" href="#注-35" aria-label="Permalink to “注”">​</a></h3><p>震為長，坤坎皆為夜，故曰夜長。離日居坎，故曰短陽，皆在陰下，坎為盜，故曰陰為陽賊，言陰賊陽也。坤為萬物、為空虛，離為枯，坤藏，坎北，故曰藏於北陸。○首句作長夜短日，依汲古。</p><h3 id="夬之家人" tabindex="-1">夬之家人 <a class="header-anchor" href="#夬之家人" aria-label="Permalink to “夬之家人”">​</a></h3><h3 id="林辭-36" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-36" aria-label="Permalink to “林辭”">​</a></h3><p>鳲鳩七子，均而不殆。長大成就，棄而合好。</p><h3 id="注-36" tabindex="-1">注 <a class="header-anchor" href="#注-36" aria-label="Permalink to “注”">​</a></h3><p>離為鳩，伏震為子，數七，故曰七子。巽為長大，坎為合。○鳲，各本訛鳴，非。殆，音以，與子韻。鳲鳩，《曹風》篇名，&quot;鳲鳩在桑，其子七兮；淑人君子，其儀一兮&quot;。</p><h3 id="夬之睽" tabindex="-1">夬之睽 <a class="header-anchor" href="#夬之睽" aria-label="Permalink to “夬之睽”">​</a></h3><h3 id="林辭-37" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-37" aria-label="Permalink to “林辭”">​</a></h3><p>三羊上山，馳至太原。黃龍負舟，遂到夷陽，究其玉囊。</p><h3 id="注-37" tabindex="-1">注 <a class="header-anchor" href="#注-37" aria-label="Permalink to “注”">​</a></h3><p>兌為羊，離卦數三，故曰三羊。伏艮為山，餘象未詳。○遂，汲古作逐。</p><h3 id="夬之蹇" tabindex="-1">夬之蹇 <a class="header-anchor" href="#夬之蹇" aria-label="Permalink to “夬之蹇”">​</a></h3><h3 id="林辭-38" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-38" aria-label="Permalink to “林辭”">​</a></h3><p>首足易處，頭尾顛倒。公為雌嫗，亂其蠶織。</p><h3 id="注-38" tabindex="-1">注 <a class="header-anchor" href="#注-38" aria-label="Permalink to “注”">​</a></h3><p>此用《夬》象。乾為首，在下，伏震為足，覆在上，故曰首足易處。乾為頭，在下，伏艮為尾，在上，故曰首尾顛倒。乾為公，上兌故曰雌嫗。巽為蠶、為織，巽覆，故曰亂其蠶織。</p><h3 id="夬之解" tabindex="-1">夬之解 <a class="header-anchor" href="#夬之解" aria-label="Permalink to “夬之解”">​</a></h3><h3 id="林辭-39" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-39" aria-label="Permalink to “林辭”">​</a></h3><p>登高望家，役事未休。王事靡盬，不得逍遙。</p><h3 id="注-39" tabindex="-1">注 <a class="header-anchor" href="#注-39" aria-label="Permalink to “注”">​</a></h3><p>詳《鼎》之《困》。</p><h3 id="夬之損" tabindex="-1">夬之損 <a class="header-anchor" href="#夬之損" aria-label="Permalink to “夬之損”">​</a></h3><h3 id="林辭-40" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-40" aria-label="Permalink to “林辭”">​</a></h3><p>畏昏不行，候旦待明。燎獵受福，老賴其慶。</p><h3 id="注-40" tabindex="-1">注 <a class="header-anchor" href="#注-40" aria-label="Permalink to “注”">​</a></h3><p>兌為昧，坤為畏、為昏，震為行，坤為閉，故曰畏昏不行。艮為明，震為旦，艮止，故曰候旦待明。震為獵，艮為火，故曰燎獵。坤為老，震為福慶。太公年八十遇文王田獵，後封於齊，故曰老賴其慶。</p><h3 id="夬之益" tabindex="-1">夬之益 <a class="header-anchor" href="#夬之益" aria-label="Permalink to “夬之益”">​</a></h3><h3 id="林辭-41" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-41" aria-label="Permalink to “林辭”">​</a></h3><p>孤獨特處，莫依為輔，心勞志苦。</p><h3 id="注-41" tabindex="-1">注 <a class="header-anchor" href="#注-41" aria-label="Permalink to “注”">​</a></h3><p>詳《益》之《艮》。</p><h3 id="夬之夬" tabindex="-1">夬之夬 <a class="header-anchor" href="#夬之夬" aria-label="Permalink to “夬之夬”">​</a></h3><h3 id="林辭-42" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-42" aria-label="Permalink to “林辭”">​</a></h3><p>戴堯扶禹，松喬彭祖。西遇王母，道路夷易，無敢難者。</p><h3 id="注-42" tabindex="-1">注 <a class="header-anchor" href="#注-42" aria-label="Permalink to “注”">​</a></h3><p>詳《訟》之《家人》。松，汲古作從，非。</p><h3 id="夬之姤" tabindex="-1">夬之姤 <a class="header-anchor" href="#夬之姤" aria-label="Permalink to “夬之姤”">​</a></h3><h3 id="林辭-43" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-43" aria-label="Permalink to “林辭”">​</a></h3><p>山石朽破，消崩墮墜。上下離心，君受其祟。</p><h3 id="注-43" tabindex="-1">注 <a class="header-anchor" href="#注-43" aria-label="Permalink to “注”">​</a></h3><p>乾為山、為石，下斷，故朽破墜墮。乾為上，巽為下，坤為心，坤伏，故離心。乾為君，陰消陽，故君受其祟。○墮墜，汲古作墜墮，不協，依宋元本。祟墜皆去聲。</p><h3 id="夬之萃" tabindex="-1">夬之萃 <a class="header-anchor" href="#夬之萃" aria-label="Permalink to “夬之萃”">​</a></h3><h3 id="林辭-44" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-44" aria-label="Permalink to “林辭”">​</a></h3><p>文母聖子，無疆壽考，為天下主。</p><h3 id="注-44" tabindex="-1">注 <a class="header-anchor" href="#注-44" aria-label="Permalink to “注”">​</a></h3><p>坤為文、為母，伏乾為聖，震為子，故曰文母聖子。艮為壽，坤為天下，伏震為主。○宋元本多人受其福四字，依汲古。</p><h3 id="夬之升" tabindex="-1">夬之升 <a class="header-anchor" href="#夬之升" aria-label="Permalink to “夬之升”">​</a></h3><h3 id="林辭-45" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-45" aria-label="Permalink to “林辭”">​</a></h3><p>倔傀無儀，前後相違。言如鱉咳，語不可知。</p><h3 id="注-45" tabindex="-1">注 <a class="header-anchor" href="#注-45" aria-label="Permalink to “注”">​</a></h3><p>坤為儀，兌剛滷，故為倔傀。倔傀，倔強貌。兌見巽伏，故曰前後相違。震為言、為咳，伏艮為鱉，初至四正反兌，故語不可知。《詩》：&quot;無非無儀，惟酒食是議&quot;。</p><h3 id="夬之困" tabindex="-1">夬之困 <a class="header-anchor" href="#夬之困" aria-label="Permalink to “夬之困”">​</a></h3><h3 id="林辭-46" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-46" aria-label="Permalink to “林辭”">​</a></h3><p>五龍俱起，強者敗走。露我苗稼，年歲大有。</p><h3 id="注-46" tabindex="-1">注 <a class="header-anchor" href="#注-46" aria-label="Permalink to “注”">​</a></h3><p>巽卦數五，伏震為龍，故曰五龍。兌為剛強，兌毀，故曰敗走。巽為苗稼，兌為雨澤，故曰露我苗稼。伏震為年歲。○敗，宋元本作敢，依汲古。</p><h3 id="夬之井" tabindex="-1">夬之井 <a class="header-anchor" href="#夬之井" aria-label="Permalink to “夬之井”">​</a></h3><h3 id="林辭-47" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-47" aria-label="Permalink to “林辭”">​</a></h3><p>豦除善疑，難為攻醫。驥疲鹽車，困於銜棰。</p><h3 id="注-47" tabindex="-1">注 <a class="header-anchor" href="#注-47" aria-label="Permalink to “注”">​</a></h3><p>詳《艮》之《夬》。伏艮為遽除，坎為疑，震為驥、為車，兌為滷，故曰鹽車。坎勞故疲睏。兌為銜，震為棰。○豦，宋元本作虎，汲古作雷，依《艮》之《夬》校。攻，宋本、汲古作功，元本作政，政者，攻形之訛，功者，攻音之訛，亦依《艮》之《夬》校。攻，治也。難，汲古作雖，依宋元本。</p><h3 id="夬之革" tabindex="-1">夬之革 <a class="header-anchor" href="#夬之革" aria-label="Permalink to “夬之革”">​</a></h3><h3 id="林辭-48" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-48" aria-label="Permalink to “林辭”">​</a></h3><p>江南多蝮，螫我手足。冤煩詰屈，痛徹心腹。</p><h3 id="注-48" tabindex="-1">注 <a class="header-anchor" href="#注-48" aria-label="Permalink to “注”">​</a></h3><p>通《蒙》。坎為江、為螫、為蝮，震為南、為足，艮為手，坎為冤煩、為詰屈、為痛、為心，坤為腹。○我，宋元本作於。</p><h3 id="夬之鼎" tabindex="-1">夬之鼎 <a class="header-anchor" href="#夬之鼎" aria-label="Permalink to “夬之鼎”">​</a></h3><h3 id="林辭-49" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-49" aria-label="Permalink to “林辭”">​</a></h3><p>心無所據，射鹿不得。多言少實，語無成事。</p><h3 id="注-49" tabindex="-1">注 <a class="header-anchor" href="#注-49" aria-label="Permalink to “注”">​</a></h3><p>通《屯》。坎為心，震為射、為鹿。正反震故曰多言，坤虛故少實。○所，汲古作可，依宋元本。無成，宋元本作成無，依汲古。</p><h3 id="夬之震" tabindex="-1">夬之震 <a class="header-anchor" href="#夬之震" aria-label="Permalink to “夬之震”">​</a></h3><h3 id="林辭-50" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-50" aria-label="Permalink to “林辭”">​</a></h3><p>君明臣賢，鳴求其友。顯德之士，可以履土。</p><h3 id="注-50" tabindex="-1">注 <a class="header-anchor" href="#注-50" aria-label="Permalink to “注”">​</a></h3><p>震為君，互艮為臣、為明、為友、為求，震為鳴、為德，艮為顯，故曰顯德。震為士、為履，坎為土。○土榮，元作事，依汲古。</p><h3 id="夬之艮" tabindex="-1">夬之艮 <a class="header-anchor" href="#夬之艮" aria-label="Permalink to “夬之艮”">​</a></h3><h3 id="林辭-51" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-51" aria-label="Permalink to “林辭”">​</a></h3><p>安上宜官，一日九遷。逾群越等，牧養常山。</p><h3 id="注-51" tabindex="-1">注 <a class="header-anchor" href="#注-51" aria-label="Permalink to “注”">​</a></h3><p>詳《履》之《節》。○上，汲古作士，群越作越群，均依宋元本。養，宋元作在，依汲古。</p><h3 id="夬之漸" tabindex="-1">夬之漸 <a class="header-anchor" href="#夬之漸" aria-label="Permalink to “夬之漸”">​</a></h3><h3 id="林辭-52" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-52" aria-label="Permalink to “林辭”">​</a></h3><p>峻詞解謝，除去垢汙。驚之成患，嬰去酷殘。</p><h3 id="注-52" tabindex="-1">注 <a class="header-anchor" href="#注-52" aria-label="Permalink to “注”">​</a></h3><p>艮山，故曰峻。峻詞，猶嚴詞也。坎為垢汙，伏震為驚，坎為患。○峻，汲古作汙，汙作活，嬰作屢，均依宋元本。去酷，宋元本作氏醳，依汲古。嬰蓋攖之叚借字。</p><h3 id="夬之歸妹" tabindex="-1">夬之歸妹 <a class="header-anchor" href="#夬之歸妹" aria-label="Permalink to “夬之歸妹”">​</a></h3><h3 id="林辭-53" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-53" aria-label="Permalink to “林辭”">​</a></h3><p>翁狂嫗盲，相牽北行。欲歸高邑，迷惑不得。</p><h3 id="注-53" tabindex="-1">注 <a class="header-anchor" href="#注-53" aria-label="Permalink to “注”">​</a></h3><p>震為翁、為狂，伏巽為嫗，兌半離，故曰嫗盲。伏艮為牽，互坎故北行。震為行、為歸，艮為高邑，坎疑，故曰迷惑不得，言不得高邑也。</p><h3 id="夬之豐" tabindex="-1">夬之豐 <a class="header-anchor" href="#夬之豐" aria-label="Permalink to “夬之豐”">​</a></h3><h3 id="林辭-54" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-54" aria-label="Permalink to “林辭”">​</a></h3><p>醉臥道傍，迷旦失明，不全我生。</p><h3 id="注-54" tabindex="-1">注 <a class="header-anchor" href="#注-54" aria-label="Permalink to “注”">​</a></h3><p>通《渙》。巽進退不果，故曰醉。震為道傍、為旦，艮為明，坎隱，故曰失明。坎破，故曰不全我生。震為生。○旦，汲古訛且，全訛合，均依宋元本。</p><h3 id="夬之旅" tabindex="-1">夬之旅 <a class="header-anchor" href="#夬之旅" aria-label="Permalink to “夬之旅”">​</a></h3><h3 id="林辭-55" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-55" aria-label="Permalink to “林辭”">​</a></h3><p>北登鬼丘，駕龍東遊。王叔御後，文武何憂。</p><h3 id="注-55" tabindex="-1">注 <a class="header-anchor" href="#注-55" aria-label="Permalink to “注”">​</a></h3><p>通《節》。坎為北、為鬼，艮丘，故曰北登鬼丘。震為龍，位東，故曰駕龍東遊。震王，艮為叔，故曰王叔。王艮善御，故不憂。離為文，伏震為武。○叔，汲古作母，依宋元本。</p><h3 id="夬之巽" tabindex="-1">夬之巽 <a class="header-anchor" href="#夬之巽" aria-label="Permalink to “夬之巽”">​</a></h3><h3 id="林辭-56" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-56" aria-label="Permalink to “林辭”">​</a></h3><p>恬淡無患，遊戲道門。與神往來，長樂以安。</p><h3 id="注-56" tabindex="-1">注 <a class="header-anchor" href="#注-56" aria-label="Permalink to “注”">​</a></h3><p>巽為伏，故曰恬淡。坎伏，故無患。伏震為遊戲，艮為道、為門，震為神，巽究成震，故曰與神往來。震為樂。○往來，汲古作來往。樂，汲古作出，均依宋元本。</p><h3 id="夬之兌" tabindex="-1">夬之兌 <a class="header-anchor" href="#夬之兌" aria-label="Permalink to “夬之兌”">​</a></h3><h3 id="林辭-57" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-57" aria-label="Permalink to “林辭”">​</a></h3><p>以緡易絲，抱布自媒。棄禮急情，卒罹憂悔。</p><h3 id="注-57" tabindex="-1">注 <a class="header-anchor" href="#注-57" aria-label="Permalink to “注”">​</a></h3><p>詳《蒙》之《困》。○憂悔，汲古作悔憂，依宋元本。緡，元本作緡，依宋本、汲古。急情，汲古作怠惰，依宋元本。</p><h3 id="夬之渙" tabindex="-1">夬之渙 <a class="header-anchor" href="#夬之渙" aria-label="Permalink to “夬之渙”">​</a></h3><h3 id="林辭-58" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-58" aria-label="Permalink to “林辭”">​</a></h3><p>被服衣冠，遊戲道門。以禮相終，身無災患。</p><h3 id="注-58" tabindex="-1">注 <a class="header-anchor" href="#注-58" aria-label="Permalink to “注”">​</a></h3><p>震為衣，艮為冠、為道、為門、為終、為身，坎為災患，震解故無。○衣，宋元本作大，災作殃，皆依汲古。</p><h3 id="夬之節" tabindex="-1">夬之節 <a class="header-anchor" href="#夬之節" aria-label="Permalink to “夬之節”">​</a></h3><h3 id="林辭-59" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-59" aria-label="Permalink to “林辭”">​</a></h3><p>大麓魚池，陸為海涯。君子失行，小人相攜。</p><h3 id="注-59" tabindex="-1">注 <a class="header-anchor" href="#注-59" aria-label="Permalink to “注”">​</a></h3><p>中爻艮為山麓，伏巽為魚，兌為池，故曰大麓魚池。兌為海，艮為陸，艮兌連體，故曰陸為海涯。艮為君子，艮止，故失行。震為人，兌小，故曰小人。艮手為攜，正反艮故曰相摧。○大，汲古作天，池作地，依宋元本。</p><h3 id="夬之中孚" tabindex="-1">夬之中孚 <a class="header-anchor" href="#夬之中孚" aria-label="Permalink to “夬之中孚”">​</a></h3><h3 id="林辭-60" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-60" aria-label="Permalink to “林辭”">​</a></h3><p>淵泉溢出，為我邑祟。道路不通，孩子心憒。</p><h3 id="注-60" tabindex="-1">注 <a class="header-anchor" href="#注-60" aria-label="Permalink to “注”">​</a></h3><p>兌為淵泉，互震出，故曰淵泉溢出。艮為我、為邑，兌毀，故曰為我邑祟。震為道路，艮止故不通。震為孩子，坎為心，卦中虛無心，故曰孩子心憒。集韻：憒，亂也。孩子與箕子音同，易林以震為孩子，是讀《明夷六五》&quot;箕子之明夷&quot;為孩子之明夷也。○我邑，汲古作邑之，依宋元本。憒，元本作貫，依宋本、汲古。</p><h3 id="夬之小過" tabindex="-1">夬之小過 <a class="header-anchor" href="#夬之小過" aria-label="Permalink to “夬之小過”">​</a></h3><h3 id="林辭-61" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-61" aria-label="Permalink to “林辭”">​</a></h3><p>十里望煙，散渙四方。形體滅亡，可入深淵，終不見君。</p><h3 id="注-61" tabindex="-1">注 <a class="header-anchor" href="#注-61" aria-label="Permalink to “注”">​</a></h3><p>詳《豫》之《觀》。○方，汲古作分，依宋元本。</p><h3 id="夬之既濟" tabindex="-1">夬之既濟 <a class="header-anchor" href="#夬之既濟" aria-label="Permalink to “夬之既濟”">​</a></h3><h3 id="林辭-62" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-62" aria-label="Permalink to “林辭”">​</a></h3><p>傳言相誤，非乾徑路。鳴鼓逐狼，不知跡處。</p><h3 id="注-62" tabindex="-1">注 <a class="header-anchor" href="#注-62" aria-label="Permalink to “注”">​</a></h3><p>詳《乾》之《無妄》。○乾，毛作好，宋元作姧，依《無妄》校。徑，汲古訛經，誤作談，依宋元本。</p><h3 id="夬之未濟" tabindex="-1">夬之未濟 <a class="header-anchor" href="#夬之未濟" aria-label="Permalink to “夬之未濟”">​</a></h3><h3 id="林辭-63" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-63" aria-label="Permalink to “林辭”">​</a></h3><p>東失大珠，西行棄稱。時多不利，使我後起。</p><h3 id="注-63" tabindex="-1">注 <a class="header-anchor" href="#注-63" aria-label="Permalink to “注”">​</a></h3><p>多用半象。漢書：終軍至關，棄襦於地。註：襦，關驗也。按：易既濟、漢書皆作繻，繻襦通用。周禮羅氏及弓人前鄭註，兩引易既作襦，又作繻，是通用也。</p>',322)])])}const f=e(l,[["render",n]]);export{p as __pageData,f as default};
